insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 1, 'HSE L108 Figure 26 works a day of 80 dBA for 5 h, 86 dBA for 2 h and 95 dBA for 45 min. What LEX,8h does the engine return for that day?', '["84.719713 dBA", "79.979400 dBA", "86.613302 dBA", "86.646970 dBA"]'::jsonb, 2, 'The three tasks are turned into energy terms, each weighted by its hours over 8, summed and turned back into decibels: 86.613302 dBA. The figure 84.719713 dBA is the task LEX of the 95 dBA task alone and 79.979400 dBA the task LEX of the 86 dBA task, so each reads one task as the day. 86.646970 dBA belongs to the EVWRENI eight-hour day, a different survey.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 2, 'Figure 26 prints the day as 87 dB(A) and 145 points, and the engine returns 86.613302 dBA and 144.987371 points. Why does that count as the engine reproducing the source?', '["The source prints whole decibels and whole points, and the engine''s figures round to both at that precision.", "The engine adds a small allowance for instrument uncertainty that closes the gap to the printed figure.", "The source rounds every LEX,8h up to the next whole decibel, so any figure between 86 and 87 would match it.", "The printed figure is taken from the points column, which always reads higher than the level column."]'::jsonb, 0, 'A reproduction is judged at the precision the source prints: 86.613302 dBA is 87 to the nearest decibel and 144.987371 points is 145 to the nearest point. The engine has no door for an uncertainty budget, no round-up rule is involved (86.613302 simply rounds to 87), and the points and the level restate one another rather than differing.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 3, 'In Figure 26, which task carries the largest share of the day''s noise exposure points?', '["The 80 dBA task, with 19.764235 points, because it runs longest at 5.000000 h.", "The 86 dBA task, with 31.473135 points, because it sits nearest the 85 dBA pivot.", "None of them, since the points are shared among the tasks in proportion to their hours.", "The 95 dBA task, with 93.750000 points in 0.750000 h."]'::jsonb, 3, 'LEX,8h is an energy average, so a task fifteen decibels louder carries far more energy in a fraction of the time: 93.750000 of the 144.987371 points sit in the last 45 minutes. Longest duration does not win, nearness to the pivot means nothing, and a share by hours is the time weighted arithmetic reading the metric does not use.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 4, 'The EVWRENI crew works a long day of 10.500000 hours. Which figure is the one to set against the EU action values?', '["86.026852 dBA, the day''s energy divided by the 10.500000 hours worked", "87.207845 dBA, the day''s energy divided by 8 hours", "86.646970 dBA, the eight-hour day''s level, since the sound levels did not change", "85.969100 dBA, the small case for ten hours at 85 dBA"]'::jsonb, 1, 'LEX,8h divides by a fixed 8 hours whatever the day''s length, so the long day reads 87.207845 dBA and the extra hours raise it. Dividing by the hours worked gives 86.026852 dBA, which is the LAeq over the day and hides the extra hours. The eight-hour day''s 86.646970 dBA ignores the longer day entirely, and 85.969100 dBA is an unrelated small case.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 5, 'For the EVWRENI long day the engine gives 87.207845 dBA, and the same energy averaged over its own hours gives 86.026852 dBA. What is the second figure?', '["The LEX,8h corrected for the long shift, which is the figure the regulation prefers.", "The LAeq over the day as worked, a different quantity from LEX,8h.", "The weekly noise exposure level of the crew, spread over five days.", "The task LEX of the loudest task on that day."]'::jsonb, 1, 'Dividing the day''s energy by 10.500000 hours instead of 8 gives the equivalent continuous sound level over the hours worked, the LAeq. It is not a corrected LEX,8h: the regulation keeps the divisor at 8 so that a longer day reads as a larger noise exposure. It involves no weekly averaging, and no single task''s LEX is involved.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 6, 'One task at 85.000000 dBA runs for 10.000000 h. What LEX,8h does the engine return?', '["85.000000 dBA", "86.760913 dBA", "84.989700 dBA", "85.969100 dBA"]'::jsonb, 3, 'Ten hours over the fixed 8 is 125.000000 points, which is 85.969100 dBA. Reading 85.000000 dBA divides the energy by the ten hours worked, the LAeq, which never moves while the level is constant. 86.760913 dBA is the LEX of 150 points, and 84.989700 dBA is four hours at 88 dBA.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 7, 'HSE L108 Appendix 3 defines noise exposure points as EP = 100 (t/8) 10^((L - 85)/10). What LEX,8h do 100 points restate?', '["85.000000 dBA", "80.000000 dBA", "87.000000 dBA", "90.000000 dBA"]'::jsonb, 0, 'Eight hours at 85 dBA is exactly 100 points, so 100 points is LEX,8h 85.000000 dBA; the engine measures that pivot as 85.000000000000 dBA. 80.000000 dBA is the lower action value at 31.622777 points, 87.000000 dBA the EU limit value, and 90.000000 dBA the OSHA criterion level from the Associate tier, which belongs to a different metric.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 8, 'A job list''s tasks add up to 150.000000 noise exposure points. What is the day''s LEX,8h?', '["88.010300 dBA", "81.989700 dBA", "86.760913 dBA", "85.969100 dBA"]'::jsonb, 2, 'LEX,8h is 85 + 10 log10(points/100), and 150 points gives 86.760913 dBA. 88.010300 dBA is the level for 200 points and 81.989700 dBA for 50, so each reads a neighbouring row; 85.969100 dBA is 125 points.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 9, 'Why can a supervisor add the noise exposure points of several tasks with ordinary arithmetic?', '["Points are a logarithmic measure like the decibel, and the logarithms of separate tasks add as the tasks themselves do.", "Each task''s points already include a threshold, so only the loud tasks are left to add.", "The points were designed as a separate limit, so their sum is compared with 145 on its own.", "Points are a linear measure of energy, so they add, and their total restates the day''s LEX,8h."]'::jsonb, 3, 'Points are proportional to energy, which adds; decibels are logarithmic and do not. The EVWRENI day''s four tasks carry 45.638640, 16.534419, 82.235865 and 1.706800 points and the engine totals 146.115723, which is the day''s LEX,8h restated. Points carry no threshold, and 145 is only Figure 26''s printed total, never a limit.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 10, 'The EVWRENI eight-hour day totals 146.115723 noise exposure points. What LEX,8h does that restate?', '["86.646970 dBA", "84.150613 dBA", "86.613302 dBA", "87.207845 dBA"]'::jsonb, 0, 'The points and the level are one quantity restated, and the engine reports the eight-hour day at 86.646970 dBA beside 146.115723 points. 84.150613 dBA is the task LEX of the 95.400000 dBA task alone, 86.613302 dBA is the Figure 26 day, and 87.207845 dBA is the same crew''s long day.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 11, 'Four hours at 88.000000 dBA gives LEX,8h 84.989700 dBA. How many noise exposure points does the engine report for it?', '["100.000000 points", "50.000000 points", "99.763116 points", "125.000000 points"]'::jsonb, 2, 'Half of eight hours at a level three decibels above the pivot is close to, and just under, 100 points: 99.763116, because three decibels is a rounding of the doubling step. Reading 100.000000 treats 3 dB as an exact doubling, 50.000000 halves the hours and forgets the level, and 125.000000 is ten hours at 85 dBA.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 12, 'The EU exports a limit value of 87.000000 dBA beside its two action values. Why does the engine return no flag against it?', '["The limit value is licensed text, so the engine may not quote it or compare a workplace LEX,8h with it in any report it writes.", "The limit value applies at the ear with hearing protection taken into account, which the engine does not compute.", "A LEX,8h above 87 is refused, so no flag is ever needed.", "The limit value only applies to the weekly noise exposure level."]'::jsonb, 1, 'LEX,8h is the level in the workplace. The limit value is read at the ear with protection allowed for, and no door computes that, so the engine returns the two action flags and none for the limit. The EU values are exported by the engine and are not licensed, nothing is refused above 87 dBA, and the value is not confined to the week.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 13, 'A report writes "above the action level" for a LEX,8h of 85.969100 dBA. What has it got wrong?', '["It names the OSHA action level, a TWA on a decibel exchange rate of 5 dB with a threshold, where the EU upper action value on LEX,8h is meant.", "Nothing, because the OSHA action level and the EU upper action value both sit at 85 and so measure the same quantity on the same survey sheet.", "It should have compared the figure with the EU limit value of 87.000000 dBA instead.", "LEX,8h can only be compared with the lower action value of 80.000000 dBA."]'::jsonb, 0, 'Both carry the number 85 and they measure different things: the OSHA action level is a TWA of 85 dBA on a decibel exchange rate of 5 dB with an 80 dBA threshold, and the EU upper action value is a LEX,8h level on the energy relation with no threshold. The limit value is read at the ear, which LEX,8h is not, and LEX,8h is compared with both action values.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 14, 'On the EVWRENI eight-hour day, what happens to the 73.800000 dBA task that lasts 1.800000 h?', '["It is dropped, because every noise metric integrates only periods at or above an 80 dBA threshold.", "It is dropped, because its task LEX of 67.321825 dBA is below the lower action value.", "It is counted for its hours at a level of zero.", "It carries 1.706800 points and is in the day''s LEX,8h, since LEX,8h has no threshold."]'::jsonb, 3, 'LEX,8h is an energy average with no floor: every task counts, however quiet, and this one adds 1.706800 points. The 80 dBA threshold belongs to the OSHA action level and NIOSH noise REL noise dose, never to LEX,8h. The action values are compared with the day''s total and never with a single task, and the task keeps its own sound level.'),
  ('hygiene', 'intermediate', 'module', 'm01-lex-eight-hour', 15, 'Someone enters a task list for `lexEightHourDbA` whose hours add up to 25. How does the engine respond?', '["A LEX,8h computed over the first 24 hours, with a warning that the last hour was trimmed", "A refusal on `periods`: \"the periods total zero hours: there is no exposure to express\"", "A refusal on `periods`: \"the periods total 25 h: a daily exposure covers at most 24 hours\"", "A LEX,8h divided by the 25 hours in place of 8, with a warning that the record is longer than a working day"]'::jsonb, 2, 'A daily noise exposure level covers at most one day, so a record over 24 hours is refused on the field `periods` with the quoted message. The engine never trims a record or changes its divisor; the zero-hours message is the refusal for a record with no time in it at all.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 1, 'A five-day week has daily LEX,8h values of 86.400000, 83.100000, 88.200000, 84.900000 and 81.700000 dBA. What weekly noise exposure level does the engine return?', '["84.860000 dBA", "85.461288 dBA", "83.414860 dBA", "88.200000 dBA"]'::jsonb, 1, 'Each day is turned into an energy term, the five terms are added, the sum is divided by 5 and turned back into decibels: 85.461288 dBA. 84.860000 dBA is the arithmetic mean of the five days, which weights a loud day the same as a quiet one; 83.414860 dBA is the week with the loud day removed; 88.200000 dBA is the loudest day read as the week.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 2, 'The five-day week reads 85.461288 dBA against an arithmetic mean of 84.860000 dBA. Why is the weekly level the higher of the two?', '["It adds a fixed penalty for every day above the upper action value, which lifts the week.", "The mean is computed over seven days of the calendar week, which pulls it down.", "The weekly level uses the loudest day as a floor and cannot fall below it.", "It is an energy average, so the loud days carry more weight than the quiet ones."]'::jsonb, 3, 'On the energy scale a day three decibels louder carries about twice the energy, so the loud days pull the energy average above the plain mean. There is no penalty term in the formula, the mean is taken over the same five days, and the weekly level sits well below the 88.200000 dBA loudest day, so that day is no floor.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 3, 'The engine is given four daily LEX,8h values for a week. By what number does it divide the sum of their energy terms?', '["5, the nominal five-day week, whatever the number of days given", "4, the number of days actually worked that week", "7, the number of days in a calendar week", "8, the reference hours of the daily level"]'::jsonb, 0, 'The judgement call J10: the weekly LEX always divides by 5 and accepts at most 7 days, so four days report days 4 and are still divided by 5. Dividing by 4 would average the days worked, dividing by 7 would spread the week over the calendar, and the 8 hour reference belongs inside each daily LEX,8h and never enters the weekly sum.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 4, 'Four days at 90 dBA give a weekly noise exposure level of 89.030900 dBA. Why does it sit below the level of every day in it?', '["The engine drops the loudest day of any week shorter than five days, so only the three remaining days are averaged into the weekly level.", "A weekly level is always about one decibel below the daily level, as a fixed allowance the regulation grants for the rest days in a week.", "Four days of energy are charged against a nominal five-day week, so the week carries less energy than five days at 90 dBA.", "The weekly formula applies the Brief and Scala weekly factor, which lowers the reading for a short week in proportion to the hours missed."]'::jsonb, 2, 'The four energy terms are divided by 5, as the J10 call writes it, so the week reads below 90. That divisor on a week that is not five days is ORACLE ONLY: the engine and an independent oracle agree, and no printed case is known to set against it. No day is dropped, there is no fixed allowance, and Brief and Scala adjust a limit in the Expert tier and never enter the weekly LEX.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 5, 'What is the evidence class of the weekly LEX on a week of four or six days?', '["Oracle only: the engine and an independent oracle agree, and no printed case with other than five days is known.", "Published and reproduced, because the L108 Figure 26 example fixes the weekly divisor as well as the energy averaging of the daily one.", "Transcription only, because the engine and the oracle copied the divisor from the same figure printed in the regulation''s text.", "Arithmetic by definition, because a weekly average has no constant other than its window."]'::jsonb, 0, 'Figure 26 reproduces the energy averaging the week shares with the day, and it says nothing about the divisor. The evidence table carries `lexWeeklyDbA` as PUBLISHED, REPRODUCED on the strength of one published case, five equal days at 85 dBA, and its note adds that the divisor of 5 is the statutory formula with no printed case of other than five days known, so on such a week the result is ORACLE ONLY. Transcription only is the class of constants two files copied from one page, and arithmetic by definition belongs to averages whose only constant is their own window.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 6, 'The weekly LEX has one published case, five equal days at 85 dBA giving 85. Why does that case fix so little?', '["It was printed to whole decibels, so it cannot catch an error in the sixth decimal of a weekly level, which is where a wrong divisor would show.", "It sits exactly on the upper action value, and a case that lands on a boundary is excluded from the golden, so the suite never checks its value.", "Any averaging of five equal numbers returns the same number, so it cannot tell the energy average or the divisor apart from anything else.", "It is taken from an ACGIH table, so its value cannot be quoted in this course."]'::jsonb, 2, 'An arithmetic mean, an energy average or a median of five days at 85 dBA all return 85, so the case would pass a wrong method. That is why the divisor of 5 is ORACLE ONLY on weeks that are not five days. The precision of the print is not the weakness, a boundary value does not exclude a case, and no licensed table is involved.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 7, 'Remove the 88.200000 dBA day from the five-day week and keep the engine''s divisor. What weekly noise exposure level results?', '["84.860000 dBA", "85.461288 dBA", "81.700000 dBA", "83.414860 dBA"]'::jsonb, 3, 'The four remaining days are still divided by 5, so the week loses the loud day''s energy and gains nothing: 83.414860 dBA. 84.860000 dBA is the arithmetic mean of all five days and 85.461288 dBA the week with the loud day still in it; 81.700000 dBA is only the quietest day.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 8, 'The five-day week falls from 85.461288 to 83.414860 dBA when the loud day is taken out. What does the second figure mean under the regulation?', '["An error, because a week without five days cannot be computed.", "The weekly level of a person who worked the other four days and was away on the loud one.", "The weekly level after the loud day has been controlled to the level of the quietest day, 81.700000 dBA.", "The arithmetic mean of the four remaining days, as the formula requires once a day is removed."]'::jsonb, 1, 'The divisor stays at 5, so four days of energy over a nominal five-day week is exactly what the regulation computes for someone absent on the loud day. The engine accepts one to seven days, the loud day is removed and not replaced at 81.700000 dBA, and the result is still an energy average.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 9, 'A crew works six days at 84.200000 dBA each, and the engine reports 84.991812 dBA for the week. What produces the rise?', '["The weekly level adds one decibel for every day worked beyond five, as the allowance for a longer week.", "Six days of energy are divided by 5, so a longer week reads above its daily level.", "The six days are rounded up to the upper action value of 85 before they are averaged into the week.", "The engine refuses six days and reports the level of five of them in their place, which reads higher."]'::jsonb, 1, 'J10 keeps the divisor at 5, so a sixth day adds energy without adding to the denominator and the week rises to 84.991812 dBA. That result, on a week that is not five days, is ORACLE ONLY. There is no per-day increment, no rounding to an action value, and the engine accepts up to 7 days.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 10, 'In the five-day week, which day would you target first for noise control, and why?', '["The 81.700000 dBA day, because the quietest day is the cheapest to improve and every day weighs one fifth.", "Any of them, since each day is one fifth of the weekly level whatever its sound level.", "The 84.900000 dBA day, because it sits nearest the upper action value.", "The 88.200000 dBA day, because the energy average gives it the largest share of the week."]'::jsonb, 3, 'The loudest day sits more than six decibels above the quietest and carries several times its energy; removing it alone drops the week from 85.461288 to 83.414860 dBA. Weighting each day as one fifth is the arithmetic mean, and nearness to an action value says nothing about a day''s share of the energy.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 11, 'From `lexAllowedDurationH`, how many hours at 94.000000 dBA alone bring the day to a LEX,8h of 85?', '["1.007140 h", "0.318486 h", "1.596210 h", "4.594793 h"]'::jsonb, 0, 'The door returns 8 x 10^((85 - 94)/10) hours, 1.007140 h. 0.318486 h is the time at the same level to reach 80, and 1.596210 h the time to reach 87, so each reads the wrong target column. 4.594793 h is the OSHA reference duration at 94 dBA from the Associate tier, a different criterion on a decibel exchange rate of 5 dB.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 12, 'Why are the hours to reach LEX,8h 85 at 85.000000 dBA exactly 8.000000?', '["85 dBA is the OSHA action level, defined as a TWA over eight hours on a decibel exchange rate of 5 dB.", "The door caps every answer at one eight-hour working shift, whatever level and target it is given.", "Eight hours at 85 dBA is LEX,8h 85 and 100 points, the pivot of the whole metric.", "The EU limit value is 87 dBA, two decibels above the target."]'::jsonb, 2, 'The reference duration T0 is 8 hours and the points pivot is 85 dBA, so the level and the target coincide at exactly 8.000000 h. The OSHA action level is a different metric on a different relation, the door caps nothing (it returns 25.298221 h at 82 dBA to 87), and the limit value has no part in this row.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 13, 'At 82.000000 dBA the door says 25.298221 hours are needed to reach LEX,8h 87. What should you read from that?', '["The engine should have refused the request, because no answer above 24 hours can be a daily figure, so the number is an error to report.", "The level is under the lower action value, so the result is set to 24 hours.", "The figure is in minutes, so the target is reached in under half an hour.", "The target cannot be reached in a day at that level; the door returns the arithmetic and leaves that reading to you."]'::jsonb, 3, 'The door answers a level and a target with a number of hours and does not refuse one above a day; noticing that 25.298221 h exceeds 24 is the reader''s job. Nothing is capped at 24 hours, and the table is in hours throughout.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 14, 'At 88.000000 dBA the hours to LEX,8h 85 are 4.009498, and at 91.000000 dBA they are 2.009509. Why is the second close to half the first but not exactly half?', '["Three decibels roughly doubles the energy, and 3 is a rounding of the exact doubling step.", "The door adds a small margin at higher sound levels to allow for the hearing protector a worker would be wearing.", "Every level above 90 dBA is capped by the OSHA table, which bends the curve.", "The two figures come from different criteria, each with its own decibel exchange rate, so they cannot halve exactly."]'::jsonb, 0, 'The hours fall by a factor of ten for every ten decibels, so three decibels divides them by a little under two, and each step of three roughly halves the hours. No protector enters the door, no OSHA table applies to the energy relation, and both figures come from the same formula.'),
  ('hygiene', 'intermediate', 'module', 'm02-the-week', 15, 'A loud task''s `lexAllowedDurationH` figure assumes it is the only task. On a real day with other tasks, how do you find the hours left at the loud task?', '["Subtract the other tasks'' hours from the table''s figure, since time is what the door returns and hours on a day add up whatever the level.", "Subtract the other tasks'' noise exposure points from the target''s points and convert the remainder into hours at the loud task''s level.", "Take the table''s figure as it stands, because the door already allows for a full day of other work.", "Average the loud task''s level with the other tasks'' levels and read the table at that average."]'::jsonb, 1, 'Points add, so the allowance left is the target''s points less the points already used, converted back into hours at the loud task''s sound level. Hours at different levels are not interchangeable, the door answers for one task in isolation, and an average of levels is not an energy quantity.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 1, 'The OSHA Technical Manual worked example puts a protector with an NRR of 25 on 98 dBA. What estimate does the field derating give?', '["80.000000 dBA", "87.600000 dBA", "77.600000 dBA", "89.000000 dBA"]'::jsonb, 3, 'The field derating takes (NRR - 7) x 50 percent off an A-weighted level: 98 less half of (25 - 7) gives 89.000000 dBA, the value the manual prints and the engine reproduces. 80.000000 dBA is the same example under Appendix B, the full (NRR - 7). 87.600000 and 77.600000 dBA belong to this tier''s teaching case, a different level and label.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 2, 'The same OSHA Technical Manual example gives 80.000000 dBA under Appendix B. Which question does that figure answer?', '["Whether the employer must turn to engineering controls before relying on protectors.", "Whether the protector is adequate for the hearing conservation programme.", "What NIOSH would credit the protector with, given the kind of protector it is.", "What a plug and a muff worn together would deliver on that level."]'::jsonb, 1, 'Appendix B of 1910.95 is the adequacy test for hearing conservation. The engineering controls question is answered by the field derating, which gives 89.000000 dBA on the same example; the NIOSH derating by type and the dual-protection rule are other methods, both ORACLE ONLY.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 3, 'An A-weighted TWA of 97.600000 dBA is worn under a protector with an NRR of 27.000000 dB. What does Appendix B estimate?', '["87.600000 dBA", "72.600000 dBA", "77.600000 dBA", "76.200000 dBA"]'::jsonb, 2, 'On A-weighted data Appendix B subtracts (NRR - 7), an attenuation of 20.000000 dB, so the estimate is 77.600000 dBA. 87.600000 dBA is the field derating, which halves that credit; 72.600000 dBA is the dual-protection rule, which adds 5 on top; 76.200000 dBA is the C-weighted teaching level under Appendix B.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 4, 'A C-weighted level of 103.200000 dBC is worn under the same NRR 27.000000 dB protector. How does Appendix B treat it?', '["It subtracts the full 27.000000 dB, giving 76.200000 dBA.", "It subtracts 20.000000 dB, taking 7 off the label as for A-weighted data.", "It refuses the level, because Appendix B is published for A-weighted data only.", "It halves the label first and then subtracts 13.500000 dB."]'::jsonb, 0, 'The engine''s Appendix B rule is C-weighted minus the NRR, so on C-weighted data the whole label is credited: 103.200000 less 27.000000 is 76.200000 dBA. Taking the 7 off is the A-weighted rule applied to the wrong weighting. The refusal of C-weighted data belongs to the field derating, and halving the label is neither method.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 5, 'On the teaching case the same NRR 27.000000 dB protector gives an attenuation of 20.000000 dB against the A-weighted level and 27.000000 dB against the C-weighted one. What accounts for the difference of 7.000000 dB?', '["The engine derates the label by protector type before crediting an A-weighted level.", "The field derating halves every credit whenever the data it is given is A-weighted.", "Appendix B credits (NRR - 7) on A-weighted data and the whole NRR on C-weighted data.", "The floor at zero removes a flat 7 dB from any credit on an A-weighted level."]'::jsonb, 2, 'The engine''s Appendix B rule is A-weighted minus (NRR - 7) and C-weighted minus the NRR, so the two attenuations on one label differ by exactly the 7, which section 3 measures as 7.000000000000 dB by taking 30 less the attenuation at an NRR of 30. Derating by type is the separate NIOSH_TYPE method, halving the credit is the field derating, and the floor applies only where the rule would give a negative attenuation.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 6, 'On the A-weighted teaching case, 97.600000 dBA with an NRR of 27.000000 dB, what attenuation does the field derating credit?', '["10.000000 dB", "20.000000 dB", "13.500000 dB", "25.000000 dB"]'::jsonb, 0, 'The field derating halves (NRR - 7): half of 20 is 10.000000 dB, leaving 87.600000 dBA. 20.000000 dB is Appendix B''s credit before halving, 13.500000 dB is half the full label with the 7 forgotten, and 25.000000 dB is the dual-protection credit.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 7, 'What does the engine return when a C-weighted level is sent to the field derating `OSHA_FIELD_50`?', '["An estimate with the full label credited, the way Appendix B treats C-weighted data, with no warning.", "A refusal on `weighting`, because the source publishes that derating for A-weighted data only.", "An estimate with 7 dB taken off first and then halved, with a warning.", "An estimate computed on the level less 7, converting the weighting."]'::jsonb, 1, 'Judgement call J5: the field derating refuses C-weighted data, in the engine''s words "the OSHA 50 percent field derating is published for A-weighted exposures only". The engine will not invent a rule the manual never wrote, so it neither borrows Appendix B''s C-weighted rule nor converts the weighting.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 8, 'In the NRR sweep on the teaching case, the gap between the field derating and Appendix B grows from 96.100000 against 94.600000 dBA at NRR 10 to 86.100000 against 74.600000 dBA at NRR 30. Why?', '["The field derating caps the credit at 10 dB, the teaching case''s figure, so any label higher than 27 stops helping it.", "Appendix B adds the 5 dB dual allowance once the label passes 20 dB, which widens the gap at the top of the sweep.", "The engine switches the field derating to C-weighting above NRR 20.", "Each decibel of label adds one decibel of credit under Appendix B and half a decibel under the field derating."]'::jsonb, 3, 'Appendix B credits NRR - 7 and the field derating (NRR - 7) x 50 percent, so the difference between them is half of (NRR - 7) and grows with the label. The field derating has no cap (it still falls to 86.100000 dBA at NRR 30), Appendix B never adds the dual 5, and the field derating refuses C-weighted data outright.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 9, 'What is the evidence class of the NIOSH derating by protector type?', '["Oracle only, since nothing printed is known to check the factors that the engine and its oracle share.", "Published and reproduced, through the OSHA Technical Manual worked example that prints an estimate for each protector type.", "Transcription only, the same class as the NIOSH heat stress equations.", "Arithmetic by definition, since a derating is a fixed fraction."]'::jsonb, 0, 'The OSHA Technical Manual example reproduces two methods only, the field derating and Appendix B. The NIOSH factors 0.750000000000, 0.500000000000 and 0.300000000000 agree between engine and oracle and nothing printed checks them, so they are ORACLE ONLY and never graded. A fixed fraction still has to be copied from a page, which is exactly what makes it more than arithmetic by definition.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 10, 'What do the NIOSH derating factors say about protector types, whatever evidence class they carry?', '["Every protector type keeps its full label, and only the A-weighting allowance of 7 dB differs by type.", "Earplugs are credited above earmuffs, because a plug sits inside the ear canal.", "One label is worth a different amount on a different kind of protector: earmuffs keep three quarters, formable earplugs half and other earplugs less than a third.", "The factors apply only to C-weighted levels, so they never change an A-weighted estimate."]'::jsonb, 2, 'The factors 0.750000000000, 0.500000000000 and 0.300000000000 say a type delivers a fraction of its label in use, and the fraction depends on the type. The 7 dB is the same for every type, earmuffs keep the largest share, and the factors apply before the A-weighted 7 is taken. This method is ORACLE ONLY and is taught for recognition.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 11, 'Under the OSHA dual-protection rule, what does the engine do with the two protectors'' labels?', '["It adds the two labels together and credits the sum against the level.", "It averages the two labels and credits the mean against the level.", "It credits each label in turn and returns one estimate for each.", "It works from the higher of the two NRRs and never from both."]'::jsonb, 3, 'The engine''s dual-protection method reads the higher NRR, subtracts 7 if the level is A-weighted and adds 5, so only one of the two labels enters the arithmetic. Nothing adds or averages the labels, and the door returns one estimate for the method it is given. The 5 dB this method adds is ORACLE ONLY and is never graded.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 12, 'A label NRR of 5 is put on 92 dBA A-weighted under Appendix B. What attenuation does the engine credit?', '["-2 dB, which raises the estimate above the unprotected level", "0.000000 dB, with a warning that the credit is floored at zero", "5 dB, the whole label, because a label below 7 is read as C-weighted", "A refusal on `nrrDb`, since a label under 7 cannot be used"]'::jsonb, 1, 'NRR - 7 would give -2 dB and raise the estimate, which no protector does, so judgement call J5 floors the credit at 0.000000 dB and the engine warns in its own words: "the method gives -2 dB of attenuation; a protector cannot raise the exposure, so the credit is zero". The weighting is never guessed from the label, and a label of zero or more is accepted.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 13, 'Which method answers whether an employer must turn to engineering controls instead of relying on hearing protectors?', '["`OSHA_APPENDIX_B`, the adequacy test of 1910.95", "`OSHA_FIELD_50`, the field derating", "`NIOSH_TYPE`, the derating by protector type", "`OSHA_DUAL`, the dual-protection rule"]'::jsonb, 1, 'The field derating is the method the digest attaches to the engineering-controls question, and it credits (NRR - 7) x 50 percent on A-weighted data. Appendix B carries the adequacy test instead, the NIOSH derating by type says what a kind of protector is worth, and dual protection says what two worn together give.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 14, 'What does the engine return when a protector call names a method it does not recognise?', '["A refusal on `method`: \"method must be one of OSHA_APPENDIX_B, OSHA_FIELD_50, OSHA_DUAL, NIOSH_TYPE\"", "An estimate under Appendix B, the default method, with a warning that the method named was not recognised", "A refusal on `protectorType`, asking for earmuff, formableEarplug or otherEarplug before any method is chosen", "An estimate by an octave-band method chosen from the label"]'::jsonb, 0, 'Every call names its method and the engine refuses an unknown one on the field `method`, in its own words. The protectorType refusal belongs to the NIOSH method alone, and the engine has no door for spectral, octave-band methods at all.'),
  ('hygiene', 'intermediate', 'module', 'm03-hearing-protector-estimates', 15, 'A report writes "protected level 87.600000 dBA" for the teaching case. What is missing?', '["Nothing, because a protected level is one figure whichever of the four methods produced it from the label.", "The C-weighted level, since every protected level must be quoted in dBC.", "The NRR, since the estimate is meaningless without the label alone.", "The method and the question it answers, here the field derating for engineering controls."]'::jsonb, 3, 'The same label and level give 77.600000 dBA under Appendix B and 87.600000 dBA under the field derating, so a figure without its method cannot tell the reader which question it answers. The estimates are in dBA, and the label on its own does not say which rule credited it.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 1, 'The worked example of 29 CFR 1910.1000(d)(1) is 150.000000 ppm for 2.000000 h, 75.000000 ppm for 2.000000 h and 50.000000 ppm for 4.000000 h. What 8-hour TWA does it give?', '["81.250000 ppm", "the plain mean of the three concentrations", "150.000000 ppm, the highest sample", "the concentration-hours divided by the three samples"]'::jsonb, 0, 'The regulation writes E = (C_a T_a + C_b T_b + ... + C_n T_n) / 8: the concentration-hours of the three samples are added and the sum divided by 8, giving 81.250000 ppm, which the engine reproduces. The plain mean ignores how long each concentration lasted, the TWA is an average and never a peak, and dividing the sum by the number of samples confuses a count with a time.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 2, 'The IGBOMOTORU partial record is 38.000000 ppm for 2.500000 h, 64.000000 ppm for 1.250000 h and 22.000000 ppm for 3.000000 h. What 8-hour TWA does the engine return?', '["35.703704 ppm", "32.468750 ppm", "30.125000 ppm", "42.156250 ppm"]'::jsonb, 2, 'The record covers 6.750000 h and is still divided by 8, as the regulation writes it: 30.125000 ppm, with a warning. 35.703704 ppm divides the same sum by the 6.750000 hours sampled; 32.468750 ppm is the full-shift record with a fourth sample, and 42.156250 ppm the ten-hour record.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 3, 'The IGBOMOTORU partial record covers 6.750000 hours and the full-shift record covers 8.000000 hours. Which of the two carries a warning?', '["Both of them, because a chemical record is warned until its limit is typed in.", "The partial record only, because a record that is not 8 hours long is warned.", "The full-shift record only, because its fourth sample was added after the rest.", "Neither of them, because the engine divides both by 8 and has nothing to report."]'::jsonb, 1, 'The table prints 1 warning for the partial record and 0 for the full shift. Judgement call J6 is that the 8-hour chemical TWA always divides by 8 and warns under or over 8 hours, and the full record covers exactly 8.000000 hours, so nothing is assumed about unsampled time and it reads 32.468750 ppm clean. No limit is typed into the door at all, and the fourth sample is what removes the warning.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 4, 'What does the engine say, in its own words, when a chemical record covers 6.750000 of the 8 hours?', '["\"the periods cover 10 h: the whole shift is divided by 8 as the regulation writes it, consider an unusual shift adjustment of the limit\"", "\"the periods cover 11 min of 15: the remainder counts as zero exposure\"", "\"the periods total 25 h: a shift covers at most 24 hours\"", "\"the periods cover 6.75 h of 8: the remainder counts as zero exposure\""]'::jsonb, 3, 'Under 8 hours the engine divides by 8, warns, and says the remainder counts as zero, which is judgement call J6. The ten-hour message is the warning for a record over 8 hours, the eleven-minute message belongs to the STEL, and the 25 h message is a refusal.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 5, 'The IGBOMOTORU full-shift record adds 15.000000 ppm for 1.250000 h. Why do its 8-hour TWA and its average over the hours covered both read 32.468750 ppm?', '["The engine switches its divisor to the hours covered whenever a record carries four samples or more.", "The fourth sample is low enough to cancel the zero the partial record assumed.", "Both figures are rounded to the same six decimals, which hides a small gap between them.", "It covers exactly 8.000000 hours, so dividing by 8 and by the hours covered are the same."]'::jsonb, 3, 'When the samples cover the whole 8 hours the two divisors coincide, so the full-shift record has one figure and no warning. The engine never changes its divisor, the fourth sample adds real concentration-hours in place of the assumed zero, and the two figures are identical before any rounding.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 6, 'The IGBOMOTORU ten-hour record covers 10.000000 hours. What 8-hour TWA does the engine return?', '["33.725000 ppm", "42.156250 ppm", "32.468750 ppm", "30.125000 ppm"]'::jsonb, 1, 'Ten hours of concentration-hours over a fixed 8 gives 42.156250 ppm, and the engine adds its unusual-shift warning. Spreading the same sum over the 10.000000 hours gives 33.725000 ppm, which understates a longer shift. The other two figures belong to the eight-hour and the 6.750000 hour records of the same crew.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 7, 'Which judgement call records that the 8-hour chemical TWA always divides by 8 and warns under or over 8 hours?', '["J6", "J7", "J2", "J10"]'::jsonb, 0, 'J6 covers both chemical averages: the 8-hour TWA always divides by 8 and warns off 8 hours, and the STEL divides by 15 and refuses over 15 minutes. J7 is the mixture index at unity, J2 the inclusive noise threshold, and J10 the weekly LEX divisor of 5.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 8, 'The full-shift TWA of 32.468750 ppm sits between the partial record''s 30.125000 and 35.703704 ppm. What does that one case show?', '["Dividing by 8 is always wrong for a short record, and the hours covered should be used instead.", "The two partial figures should be averaged to estimate the full-shift TWA.", "The zero for unsampled time is an assumption, and a measurement can overturn it.", "The fourth sample must have been measured wrongly, since it moved the TWA upwards."]'::jsonb, 2, 'The unsampled time was not zero, so the true 8-hour TWA sits between the two claims the partial record offered. It is one case and proves nothing general: dividing by 8 is still what the regulation writes, averaging the two claims is a method nobody printed, and a sample that adds concentration-hours is expected to raise the TWA.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 9, 'A full fifteen-minute record is 240.000000 ppm for 5.000000 minutes and 110.000000 ppm for 10.000000 minutes. What STEL does the engine return?', '["the mean of the two concentrations", "240.000000 ppm, the peak", "153.333333 ppm", "the sum of concentration-minutes over 10"]'::jsonb, 2, 'The STEL is sum(C t) / 15 with t in minutes: the concentration-minutes of the two samples are added and divided by 15, giving 153.333333 ppm. A mean of the two concentrations ignores their minutes, the peak is not a time weighted average, and 10 is the length of one sample, never the window.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 10, 'An eleven-minute sample set, 180.000000 ppm over 4.000000 min then 95.000000 ppm over 7.000000 min, is sent to `chemicalStel15Min`. What comes back?', '["92.333333 ppm, divided by 15, with a warning that the remaining minutes count as zero", "The concentration-minutes divided by the 11.000000 minutes covered, with no warning", "A refusal, because a STEL record must cover exactly 15 minutes", "153.333333 ppm, after the record is scaled up to a full window"]'::jsonb, 0, 'Under 15 minutes the STEL still divides by 15 and warns "the periods cover 11 min of 15: the remainder counts as zero exposure", so the concentration-minutes of the two samples over 15 give 92.333333 ppm. Dividing by the minutes sampled assumes the missing minutes were like the sampled ones; the refusal is for records over 15 minutes; and 153.333333 ppm is the other record.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 11, 'A STEL record totals 16 minutes. What does the engine return, in its own words?', '["A STEL divided by the 16 minutes covered, with a warning that the window was stretched past fifteen", "A STEL divided by 15 as usual, with a warning that the extra minute was counted inside the window", "A STEL over the first 15 minutes, with the last minute trimmed", "A refusal on `periods`: \"the periods total 16 min: a short-term exposure is a 15-minute window\""]'::jsonb, 3, 'Over 15 minutes the engine refuses, which is judgement call J6. Dividing by 16 would make a sixteen-minute average that is no STEL, dividing by 15 would crowd sixteen minutes into a fifteen-minute window, and trimming would mean choosing which minute to drop, a decision the engine has no basis for.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 12, 'The engine warns on a STEL record under 15 minutes and refuses one over 15. Why the difference?', '["Records under 15 minutes are common in the field and records over 15 minutes are rare, so the engine supports only the common case and refuses the rare one.", "A shorter record still fits the fifteen-minute window once the remainder counts as zero; a longer record is longer than the window itself.", "The source prints a worked example of a short record and none of a long one, so the engine follows the only case that a printed value fixes for it.", "A long record would push the STEL above its limit."]'::jsonb, 1, 'The STEL is sum(C t) / 15 with t in minutes, so a record under fifteen minutes stays inside that window once the unsampled remainder counts as zero, and the engine warns to name the assumption. A record over fifteen minutes is longer than the window the STEL is defined on, and judgement call J6 records the choice: the STEL divides by 15 and refuses over 15 minutes. The door has no published case of either length, so a printed example fixes nothing here, and frequency and the limit have nothing to do with it.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 13, 'How strong is the evidence behind the STEL''s arithmetic?', '["It is a fifteen-minute time weighted average whose only constant is the window, so there is nothing to transcribe beyond the averaging.", "It is published and reproduced, through a STEL example printed beside the 8-hour TWA example in 1910.1000(d)(1) and matched by the engine.", "It is oracle only, because no source prints the fifteen-minute divisor.", "It rests on a licensed table and so cannot be checked in this course."]'::jsonb, 0, 'The STEL is arithmetic by definition: its only constant is the length of its window, 15 minutes, which the engine measures as 15.000000000000. The (d)(1) example is an 8-hour TWA case and prints no STEL, the window is the definition itself rather than a copied constant, and no licensed table is involved.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 14, 'A chemical record gives its first period a concentration below zero. What does the engine return?', '["A TWA with the negative period counted as zero concentration, and a warning naming the period", "A TWA that subtracts the negative period''s concentration-hours from the sum before dividing by 8", "A refusal on `periods`: \"the periods total 25 h: a shift covers at most 24 hours\"", "A refusal on `periods[0].concentration`: \"periods[0].concentration cannot be negative\""]'::jsonb, 3, 'A concentration below zero has no meaning, so the engine refuses on the field that names the period, in its own words. It never silently repairs an input by zeroing or subtracting it, and the 25 h message is the refusal for a record longer than a day.'),
  ('hygiene', 'intermediate', 'module', 'm04-chemical-averages', 15, 'The engine is given a long record of short samples. Does it search them for the worst fifteen minutes when it computes a STEL?', '["Yes; it slides a fifteen-minute window along the record and reports the highest average.", "No; it averages only the periods it is given, and choosing the window is the hygienist''s decision.", "Yes; it keeps the fifteen minutes with the highest single sample and drops the rest.", "No; it averages the whole record over its own length and reports that as the STEL."]'::jsonb, 1, 'The door averages the periods it receives, and a record over 15 minutes is refused, so the window has to be chosen at sampling time, around the task that makes the peak. The engine has no sliding window, keeps no highest sample, and averaging a long record over its own length is no STEL.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 1, 'The teaching mixture is toluene 72.500000 ppm against 200.000000, xylene 31.200000 ppm against 100.000000 and acetone 385.000000 ppm against 1000.000000. What mixture index does the engine return?', '["0.385000", "1.059500", "0.925000", "1.100000"]'::jsonb, 1, 'The index is the sum of each concentration over its own limit: 0.362500 + 0.312000 + 0.385000 = 1.059500. 0.385000 is only the largest single term, which reads the mixture by its worst component; 0.925000 is the published example''s index and 1.100000 the golden''s over-unity case.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 2, 'In the teaching mixture, what is the toluene term?', '["0.362500", "0.312000", "0.385000", "the limit of 200.000000 divided by 72.500000"]'::jsonb, 0, 'A term is the concentration over its own limit, 72.500000 over 200.000000, which is 0.362500. 0.312000 is the xylene term and 0.385000 the acetone term. Dividing the limit by the concentration inverts the ratio and gives a number above 1 for a component well under its limit.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 3, 'Every term of the teaching mixture is under 1, and the index is 1.059500. What does that show?', '["The engine has made an error, since a sum of three terms that are each under 1 can never pass 1 when they are added.", "The mixture passes, because the largest term, 0.385000, is the figure the regulation compares with unity.", "Only acetone needs control, because its term is the largest of the three and the other two add nothing.", "Components that each look acceptable alone can together use more than the whole combined allowance."]'::jsonb, 3, 'Three terms of 0.362500, 0.312000 and 0.385000 add to more than 1, which is the whole point of the index: a report that checked each component against its own limit would find nothing. The largest term is not what the regulation compares with unity, and no single component explains the excess.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 4, 'The worked example of 1910.1000(d)(2) is 500.000000 against 1000.000000, 45.000000 against 200.000000 and 40.000000 against 200.000000. What does the engine return?', '["Terms 0.500000, 0.225000 and 0.200000, and an index of 0.500000, the largest term", "Terms 0.500000, 0.225000 and 0.200000, and an index of 1.059500", "Terms 0.500000, 0.225000 and 0.200000, and an index of 0.925000", "An index of 0.925000 with every term reported as absent"]'::jsonb, 2, 'Each concentration over its limit gives 0.500000, 0.225000 and 0.200000, and they add to 0.925000, which the engine reproduces from the regulation''s own example. The largest term is not the index, 1.059500 belongs to the teaching mixture, and the engine always reports each term.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 5, 'Why does the engine reproducing the printed (d)(2) example matter, when an additive index is so simple to code?', '["It is the only way to know which of the limits in the example are licensed.", "It proves the additive model is right for every mixture the engine will see.", "It fixes the tolerance the capstone grades the mixture index at.", "It sets the rule against a value the source itself prints, so a misreading shared by the engine and its oracle would be caught."]'::jsonb, 3, 'A printed case reproduced at the precision it prints is what this course calls PUBLISHED, REPRODUCED: two people copying the same page wrongly would be caught by that value. It says nothing about which limits are licensed, it cannot prove that additivity suits a given mixture, and a printed example fixes a rule''s arithmetic and says nothing about how any answer is scored.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 6, 'The published example has a largest term of 0.500000 and an index of 0.925000; the teaching mixture has a largest term of 0.385000 and an index of 1.059500. What does the comparison teach?', '["The index depends only on the sum, so the mixture with the larger single term can be the one that stays under unity.", "The mixture with the larger single term always exceeds first, so the teaching mixture''s index must have been misreported by the engine.", "The index weights the largest term double before adding the others, which is why the published example stays under unity.", "The two cases cannot be compared at all, because one types public OSHA limits and the other types limits from a licensed table."]'::jsonb, 0, 'The index does not care how the sum is shared out: many moderate terms can exceed where one large term does not. Nothing weights the largest term, the teaching mixture''s report is correct, and both cases type public OSHA values as limits, so they compare directly.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 7, 'Acetone at 385.000000 ppm and xylene at 31.200000 ppm carry terms of 0.385000 and 0.312000. How should a mixture be screened?', '["Rank by concentration, so acetone at 385.000000 ppm dominates the mixture by far.", "Rank by limit, since the component with the lowest limit always carries the largest term.", "Rank the components by their terms, since each concentration is divided by its own limit.", "Rank by molecular weight, which the engine applies to each term."]'::jsonb, 2, 'Concentrations more than ten times apart give terms of similar size because each is divided by its own limit, so the terms are what show where the combined allowance is spent. A low limit alone does not decide a term without its concentration, and the engine takes no molecular weight.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 8, 'A mixture''s terms add to exactly 1.000000. What does the engine report, and which judgement call decides it?', '["Exceeds true, by J7: an index of 1 has reached the limit.", "Exceeds false, by J7: an index of exactly 1 passes.", "Exceeds false, by J2: a boundary is always inclusive.", "A refusal, since an index on the boundary is undefined."]'::jsonb, 1, 'The regulation says the index "shall not exceed unity", and an index equal to unity has not exceeded it, so exceeds is true only above 1. The call is J7. J2 is the Associate tier''s inclusive noise threshold, a different call on a different boundary, and nothing is refused at 1.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 9, 'The teaching mixture''s terms are 0.362500, 0.312000 and 0.385000 against limits of 200.000000, 100.000000 and 1000.000000 ppm. What happens if a different limit is typed for one component?', '["That component''s term changes with its own limit and the other two are untouched.", "Every term is rescaled, since the index divides its sum by the largest limit.", "Nothing moves until the index passes 1, where the engine reads the limits again.", "The door refuses the mixture, because its first limits are the ones it holds."]'::jsonb, 0, 'Each term is one component''s concentration over that component''s own limit, so a limit belongs to one term alone: change the 1000.000000 ppm acetone limit and only the 0.385000 term moves, while toluene''s 0.362500 and xylene''s 0.312000 stay as they are. There is no shared divisor in the sum, the engine holds no limit table to read again, and every limit is an input the caller types.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 10, 'If the three components of the teaching mixture acted on different organs independently, what should be compared with what?', '["The sum of the terms against 1, since the regulation writes the sum.", "Each term against 1 on its own, where the largest is 0.385000.", "The sum of the terms against 3, one allowance per component.", "The largest concentration against the smallest limit."]'::jsonb, 1, 'Where components act independently each is compared against its own limit and the sum means nothing, so the reading is three terms each under 1. The sum is the right model only for components acting on the same organ by the same mechanism; a sum against 3 and a cross-comparison of concentration and limit are not methods anyone prints.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 11, 'Where one component is known to potentiate another, what does the additive index do?', '["It overstates the hazard, so a mixture above unity may in fact be safe to leave as it is.", "It gives the right answer, because potentiation is already built into each substance''s limit.", "It understates the hazard, so the index is a floor and should be reported as one.", "It cannot be computed, so the engine refuses the mixture on the field `components`."]'::jsonb, 2, 'Potentiation means the components together do more harm than either alone, so a sum that only adds understates it, and a mixture below unity can still be a problem. Limits are set per substance and hold no interaction, and the engine computes the additive index whatever the mechanism, since it cannot tell which case a mixture is in.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 12, 'Which of these is outside what `mixtureExposureIndex` can tell you?', '["Each component''s concentration divided by its own limit, one term per component.", "Whether the sum of the terms is above 1, which the door returns as a flag.", "Which component carries the largest term.", "Whether the components act on the same organ by the same mechanism."]'::jsonb, 3, 'The door returns each term, the index and whether it exceeds 1, from which the largest term can be read. The mechanism of action is toxicology the engine does not hold, so the choice of model has to be made, and written down, outside it.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 13, 'A mixture is entered with a limit of zero for its first component. What does the engine return?', '["A term of zero for that component, and an index built from the other components with a warning", "An infinite term and exceeds true, since any concentration at all is over a limit of zero", "A refusal on `components`: \"components must be a non-empty array\"", "A refusal on `components[0].limit`: \"components[0].limit must be a finite number above zero\""]'::jsonb, 3, 'Each term divides by its limit, and a limit of nothing would make that division meaningless, so the door stops and points at the first component''s limit. Dropping the component or reporting an infinite term would both hide a typing error in the list; the non-empty array message belongs to a list with no components in it.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 14, 'A mixture lists a component at a concentration of zero. How does the engine treat it?', '["It accepts it, and the component contributes a term of zero.", "It refuses it, because a concentration of zero is treated like a limit of zero.", "It drops the component and warns that the mixture list has shrunk.", "It credits the component with its full limit as a term of 1."]'::jsonb, 0, 'A concentration of zero is the right answer for a component that is listed and absent, so its term is zero. A limit of zero is refused because no substance has an allowance of nothing, and that asymmetry is deliberate. The engine neither drops nor inflates a zero component.'),
  ('hygiene', 'intermediate', 'module', 'm05-mixtures', 15, 'A report compares a personal air sample''s 8-hour TWA of an aromatic solvent with BTEX emitted from a glycol unit. Where does the emission question belong?', '["This tier, since the mixture index covers any aromatic solvents.", "Safety Performance Statistics, since an emission is an incident.", "The Gas Processing course, which owns BTEX as an emission from a glycol unit.", "The Risk, Change and Learning course, since it owns every hazard."]'::jsonb, 2, 'BTEX as an emission from a glycol unit is a different measurement of a different quantity from a personal air sample and its 8-hour TWA, and the Gas Processing course owns it. This tier''s concern is the breathing zone. Safety Performance Statistics owns incident rates and Risk, Change and Learning the 5x5 risk matrix.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 1, 'Every average in this tier divides by a fixed reference. Which pairing of metric and reference is right?', '["The weekly LEX and the days worked", "The chemical TWA and the hours sampled", "The STEL and 15 minutes", "LEX,8h and the hours of the shift"]'::jsonb, 2, 'The STEL divides by 15 minutes whatever the record covers. The weekly LEX divides by 5 days, the chemical TWA by 8 hours, and LEX,8h by 8 hours, so the long EVWRENI day reads 87.207845 dBA and the partial IGBOMOTORU record 30.125000 ppm. Each wrong pairing replaces the fixed reference with the time actually covered.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 2, 'Under the fixed-reference pattern of this tier, what happens to a record that covers more time than its reference?', '["Its figure is rescaled back to the reference length, so any extra time on the record changes nothing.", "The engine refuses every record longer than its reference.", "The figure falls, because the extra time dilutes the average.", "Its figure rises, because the extra time adds to the sum while the divisor stays put."]'::jsonb, 3, 'More time than the reference raises the figure: ten hours at 85 dBA read LEX,8h 85.969100 dBA and the ten-hour chemical record 42.156250 ppm. Nothing is rescaled, only the STEL refuses a record over its window, and a dilution would need the divisor to grow with the record.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 3, 'The noise figures of this tier are energy averages and the chemical figures arithmetic ones. What follows for a short, high reading?', '["Both behave alike, since both are time weighted averages over 8 hours.", "A short loud task can decide a LEX,8h; a short high sample moves a chemical TWA only in proportion to its concentration and hours.", "A short high chemical sample decides the TWA, and a short loud task barely moves LEX,8h.", "Neither can be moved by a short reading, because both divide by 8 hours."]'::jsonb, 1, 'On a decibel scale three decibels roughly doubles the energy, so the 95 dBA task of Figure 26 carries 93.750000 of its 144.987371 points in 45 minutes. A chemical TWA is a plain time weighted mean of concentrations, where every ppm counts the same. The shared divisor of 8 hours does not make the two scales behave alike.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 4, 'Which protector estimate does this tier grade, and what fixes it?', '["The field derating, fixed by the OSHA Technical Manual''s printed 89.000000 dBA", "Appendix B, fixed by the manual''s printed 80.000000 dBA for the hearing conservation question", "The NIOSH earmuff derating, fixed by the NIOSH criteria document", "The dual-protection rule, fixed by the 5 dB in 1910.95"]'::jsonb, 0, 'The capstone takes its protector estimate by the field derating, for the engineering controls question, and the manual prints 89.000000 dBA for its worked example, which the engine reproduces. Appendix B is also reproduced, at 80.000000 dBA, and answers the hearing conservation question the capstone does not ask. The NIOSH derating by type and dual protection are ORACLE ONLY, and nothing printed fixes either.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 5, 'The NIOSH derating by type and the OSHA dual-protection 5 dB are taught and never graded. What is the reason?', '["They are licensed material, so their factors cannot be typed into the engine or quoted in any lesson of the course.", "They are oracle only: an independent oracle agrees with the engine and no printed value is known to set against either.", "They give the same figures as Appendix B on every label, so grading them as well would only duplicate a graded field.", "They are Expert tier material and are only previewed in this tier."]'::jsonb, 1, 'Section 23 lists both among the items this course never grades, and gives oracle only as the reason for each: nothing a source prints stands outside the engine and its oracle to check them. Neither is licensed, since the engine holds the factors; they give different figures from Appendix B, 84.350000 dBA for an earmuff against 77.600000 dBA on the teaching case; and both are taught in full in this tier.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 6, 'Under what condition is a weekly LEX graded in this course?', '["On any week of up to seven days, since the engine accepts up to seven.", "Only on weeks of four days, where the divisor matters most.", "Only where the statutory divisor of 5 equals the number of days given, so no constant the evidence cannot fix moves the answer.", "Never; the weekly LEX is oracle only and taught for recognition."]'::jsonb, 2, 'On a five-day week the divisor and the day count agree, so the energy averaging reproduced by Figure 26 is all that sets the answer. On a four or six day week the divisor of 5 is ORACLE ONLY, which is why the capstone gives five days and J10''s boundary is never tested. The weekly LEX on five days is graded, so it is not merely taught.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 7, 'No capstone input in this tier sits on a judgement call''s boundary. Which boundary belongs to J5?', '["A protector credit reaching the floor at zero", "A mixture index landing exactly on unity", "A record that leaves unsampled time undeclared", "A weekly LEX fed a number of days other than five"]'::jsonb, 0, 'J5 floors protector credit at 0 with a warning and refuses C-weighted data for the field derating. Unity is J7, unsampled time is J6, and a week of other than five days is J10. The calls are taught by name so they can be recognised in a real survey, and the capstone keeps clear of all four.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 8, 'A reviewer asks for a question whose answer is the word "exceeds" for the teaching mixture. Why does this course not grade that?', '["The teaching mixture does not exceed, so the word would be false.", "A verdict needs a licensed limit, which the course never quotes.", "Risk, Change and Learning owns verdicts, so the word belongs there.", "Verdict words are never graded in this course, and section 23 lists them among what it leaves out."]'::jsonb, 3, 'Section 23''s list of what this course never grades carries any verdict word: exceeds, passes, at or above an action value. The teaching mixture does exceed at an index of 1.059500, its limits are public OSHA values typed as inputs, and the risk matrix is the only thing Risk, Change and Learning owns here.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 9, 'Where do the exposure limits used in this course come from?', '["An ACGIH table embedded in the engine supplies them, quoted with permission and updated whenever the table is reissued.", "The engine looks them up in its own table by substance name, so the caller only has to type the concentration.", "ISO 9612 supplies them, and the engine applies it to every chemical record.", "They are typed into the engine as inputs from public OSHA or NIOSH values; no licensed limit is quoted."]'::jsonb, 3, 'The engine embeds no limit table and never looks one up; every limit is an input, and this course types only public OSHA or NIOSH values. ACGIH TLVs, ISO 9612 and ISO 7243 text are licensed and never quoted, and ISO 9612 is a noise measurement standard in any case.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 10, 'A learner wants to add the plant''s incident rate to a noise exposure report built in this tier. Which course owns incident rates?', '["This course, as part of the capstone", "Safety Performance Statistics, the first course of this module", "The Risk, Change and Learning course, together with the 5x5 matrix", "The Separation and Relief courses"]'::jsonb, 1, 'Incident and injury rates belong to Safety Performance Statistics, the first course of this module. The 5x5 risk matrix belongs to Risk, Change and Learning, and flare and pool-fire thermal radiation to Separation and Relief. This course cites them and stops there.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 11, 'A site manager wants the field derated 87.600000 dBA compared with the EU limit value of 87.000000 dBA. Why does this course refuse that comparison?', '["The limit value applies at the ear with protection taken into account, and none of the four estimates is that assessment.", "87.000000 dBA is a licensed value from the directive, so the course may not quote it or compare any figure with it.", "Every protector estimate is C-weighted while the directive''s limit value is A-weighted, so the two can never be set side by side.", "The limit value applies only to the weekly noise exposure level, and a protector estimate is a daily figure for one shift."]'::jsonb, 0, 'A field derated figure is a rule applied to a label for the engineering controls question, and the directive''s limit value needs a real assessment at the ear with the protector in place, which no door computes. The directive''s figures are public and carried by the engine, every estimate here is in dBA, and the limit value covers the day as well as the week.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 12, 'On the teaching case the field derating leaves 87.600000 dBA and Appendix B 77.600000 dBA. A hygienist quotes 77.600000 dBA to argue that engineering controls are unnecessary. What is the error?', '["None, because the lower estimate is the more accurate of the two, and an accurate estimate settles any question put to it.", "They should have quoted the dual-protection estimate instead, which is the lowest of all and so the strongest argument available.", "They answered the engineering controls question with the more generous rule; that question belongs to the field derating.", "They should have averaged the two estimates, so that neither the harsh rule nor the generous one decides the answer alone."]'::jsonb, 2, 'The field derating credits 10.000000 dB where Appendix B credits 20.000000 dB on the same label and the same level, and the digest gives each estimate its own question: the field derating answers whether engineering controls are needed. The lower figure answers the other question rather than answering this one more accurately, dual protection is ORACLE ONLY and answers a third, and averaging two methods is no method at all.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 13, 'Which of these does this course put among its eighteen graded capstone fields?', '["A WBGT built from globe, wet bulb and dry bulb readings", "Chemical averages and indices", "A margin against the NIOSH heat REL at a stated metabolic rate", "The Brief and Scala weekly reduction factor taken on its own"]'::jsonb, 1, 'The eighteen graded fields are noise doses and TWAs, LEX values, the OSHA engineering-controls protector estimate, chemical averages and indices, reduction-factor arithmetic, and two one-hour averages of readings the capstone states. Section 23 removes the other three by name: no WBGT built from thermometer readings and no margin against a NIOSH heat stress limit, because those constants are checked for transcription only, and the Brief and Scala weekly factor on its own, because it is oracle only.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 14, 'Which two figures among the tier''s teaching cases come back with a warning that unsampled time counts as zero?', '["The partial IGBOMOTORU record''s 8-hour TWA and the short STEL record", "The long EVWRENI day''s LEX,8h and the five-day weekly noise exposure level", "The field derated estimate and the mixture index", "The full-shift IGBOMOTORU record and the full STEL window"]'::jsonb, 0, 'The partial record covers 6.750000 of 8 hours and the short STEL record 11.000000 of 15 minutes, and each warns that the remainder counts as zero. LEX,8h and the weekly LEX carry no such warning, the protector estimate carries its method, and the full records cover their whole reference.'),
  ('hygiene', 'intermediate', 'module', 'm06-the-professional-capstone', 15, 'Before submitting, a learner checks each figure''s units. Which slip gives a clean-looking number that answers nothing?', '["A mixture index quoted without a unit, since every figure in the capstone must carry a unit beside it.", "A STEL quoted in ppm, since a fifteen-minute average ought to be quoted in ppm-minutes as it is summed.", "A LEX,8h quoted in dBA, since a daily level should be quoted in noise exposure points as the regulation does.", "A level typed in the wrong weighting, or a duration typed in minutes where hours are asked for."]'::jsonb, 3, 'A wrong weighting changes which rule credits a protector, and minutes typed as hours change every time weighted average, and neither is caught by the arithmetic. An index is dimensionless, a STEL is in ppm and a LEX,8h in dBA, so each of those is correct as written.'),
  ('hygiene', 'intermediate', 'final', null, 1, 'How many noise exposure points does the engine report for the whole Figure 26 day?', '["146.115723 points", "93.750000 points", "166.258750 points", "144.987371 points"]'::jsonb, 3, 'The three task points, 19.764235, 31.473135 and 93.750000, belong to one day whose total the engine reports as 144.987371, printed by the source as 145. 146.115723 points is the EVWRENI eight-hour day and 166.258750 its long day; 93.750000 is the 95 dBA task on its own.'),
  ('hygiene', 'intermediate', 'final', null, 2, 'The EVWRENI crew''s 10.500000 hour day is run through `lexEightHourDbA`. What points total does the engine report?', '["146.115723 points", "166.258750 points", "125.000000 points", "144.987371 points"]'::jsonb, 1, 'More hours at the same sound levels add energy over the same fixed 8 hours, so the long day carries 166.258750 points, which restates its LEX,8h of 87.207845 dBA. 146.115723 points is the same crew''s eight-hour day, 125.000000 points is ten hours at 85 dBA, and 144.987371 points is Figure 26.'),
  ('hygiene', 'intermediate', 'final', null, 3, 'A survey sheet lists 86.026852 dBA in the LEX,8h column for the EVWRENI long day. What has the surveyor done?', '["Averaged the day''s energy over the 10.500000 hours worked, which is the LAeq and hides the extra hours.", "Nothing wrong: the engine prints 86.026852 dBA as the long day''s LEX,8h.", "Applied the weekly divisor of 5 to a single day by mistake.", "Left out the quietest task, which lowered the day''s energy."]'::jsonb, 0, 'LEX,8h divides by a fixed 8 hours, so the long day''s figure is 87.207845 dBA; dividing the same energy by its own hours gives 86.026852 dBA, the equivalent continuous level over the day. No weekly divisor is involved, and dropping a quiet task would barely move either figure.'),
  ('hygiene', 'intermediate', 'final', null, 4, 'In Figure 26, what task LEX does the engine give the 95 dBA task that lasts 45 min?', '["77.958800 dBA", "86.613302 dBA", "84.719713 dBA", "79.979400 dBA"]'::jsonb, 2, 'A task LEX is the task''s own energy term over 8 hours in decibels: three quarters of an hour at 95 dBA is 84.719713 dBA. 77.958800 dBA is the 80 dBA task and 79.979400 dBA the 86 dBA task; 86.613302 dBA is the whole day.'),
  ('hygiene', 'intermediate', 'final', null, 5, 'The EVWRENI eight-hour day''s task 3 is 95.400000 dBA for 0.600000 h and carries 82.235865 of the day''s 146.115723 points. What does that tell a supervisor?', '["That one short task carries more than half the day, so it is the one to change first.", "That the task should be dropped from the sheet, because it lasts under an hour.", "That the day''s total is wrong, since no task under an hour can carry half the points.", "That the other three tasks together decide the day, since they take up most of its 8 hours."]'::jsonb, 0, 'Points are energy, and a short loud task carries far more energy than its hours suggest, so the 95.400000 dBA task holds more than half the total. Its duration does not remove it, the total is the engine''s own, and hours alone do not decide a share of the energy.'),
  ('hygiene', 'intermediate', 'final', null, 6, 'A points total of 320.000000 is converted with `lexFromExposurePointsDbA`. What LEX,8h results?', '["88.010300 dBA", "90.051500 dBA", "91.989700 dBA", "95.000000 dBA"]'::jsonb, 1, 'The conversion is 85 plus ten times the base-ten logarithm of the points over 100, and for 320 that lands at 90.051500 dBA. The three wrong levels are real rows of the points table read at the wrong total: 200 points for 88.010300, 500 for 91.989700 and 1000 for 95.000000 dBA.'),
  ('hygiene', 'intermediate', 'final', null, 7, 'In noise exposure points, where does the EU lower action value of 80.000000 dBA sit?', '["31.622777 points", "50.000000 points", "25.000000 points", "10.000000 points"]'::jsonb, 0, 'Eight hours at 80 dBA is 31.622777 points, the points figure that restates LEX,8h 80.000000 dBA. 50.000000 points is 81.989700 dBA, 25.000000 points is 78.979400 dBA and 10.000000 points is 75.000000 dBA.'),
  ('hygiene', 'intermediate', 'final', null, 8, 'A spreadsheet averages the five daily LEX,8h values 86.400000, 83.100000, 88.200000, 84.900000 and 81.700000 dBA and reports 84.860000 dBA as the week. What should it report?', '["84.860000 dBA, since the plain mean is the regulation''s weekly level", "88.200000 dBA, since the loudest day sets the week", "83.414860 dBA, the week once the loud day is discounted", "85.461288 dBA, the energy average over five days"]'::jsonb, 3, 'The weekly noise exposure level energy-averages the days over a fixed five, which lets the loud days weigh what their energy earns: 85.461288 dBA. The plain mean treats every day as one fifth. The loudest day is not the week, and discounting a day that was worked has no basis in the formula.'),
  ('hygiene', 'intermediate', 'final', null, 9, 'Four days of 89.500000, 87.100000, 90.200000 and 86.300000 dBA give a weekly level of 87.600937 dBA, below their arithmetic mean of 88.275000 dBA. How should that result be reported?', '["As a published and reproduced value, since Figure 26 fixes the weekly formula along with the daily one.", "As an error, since an energy average of the same days can never fall below their arithmetic mean.", "As the statutory formula''s result on a four-day week, whose divisor of 5 is oracle only.", "As the mean of the four days, since the engine divides a four-day week by 4."]'::jsonb, 2, 'J10 divides every week by 5, so four days of energy over a nominal five-day week reads below the days'' own mean. On a week that is not five days no printed case is known, so the divisor is ORACLE ONLY and the figure should be reported as arithmetic defended from the written formula. Figure 26 fixes only the daily energy averaging, and the engine never divides by 4.'),
  ('hygiene', 'intermediate', 'final', null, 10, 'A task runs at 100.000000 dBA. After how many hours on its own has it used the whole allowance up to the EU lower action value?', '["0.252982 h", "0.080000 h", "2.000000 h", "0.400950 h"]'::jsonb, 1, 'Eight hours times ten to the power (80 - 100)/10 is 0.080000 h, under five minutes. 0.252982 h and 0.400950 h aim at 85 and 87 instead of the lower action value. 2.000000 h is what the Associate tier''s OSHA criterion allows at 100 dBA for a full noise dose, a different metric with a different decibel exchange rate.'),
  ('hygiene', 'intermediate', 'final', null, 11, 'A 97.000000 dBA task is the only noise on a shift. After how long does the day reach LEX,8h 87?', '["0.504766 h", "3.031433 h", "0.159621 h", "0.800000 h"]'::jsonb, 3, 'At 97 dBA the hours to 87 are 8 x 10^(-1), 0.800000 h. 0.504766 h is the time to 85 and 0.159621 h the time to 80; 3.031433 h is the OSHA reference duration at 97 dBA, a different criterion on a different relation.'),
  ('hygiene', 'intermediate', 'final', null, 12, 'The OSHA Technical Manual example, 98 dBA and an NRR of 25, gives two estimates. Which one belongs in a decision on engineering controls?', '["89.000000 dBA, from the field derating", "80.000000 dBA, from Appendix B", "the lower of the two, whichever method gave it", "the mean of the two estimates"]'::jsonb, 0, 'The digest labels the two estimates by their questions: 89.000000 dBA under the field derating is the engineering-controls answer and 80.000000 dBA under Appendix B the hearing-conservation one, from one example with one protector. Taking the lower figure answers the other question, and a mean of two methods is no method.'),
  ('hygiene', 'intermediate', 'final', null, 13, 'Move the teaching protector''s label up to 30.000000 dB. Under `OSHA_FIELD_50`, what level is left on 97.600000 dBA?', '["74.600000 dBA", "69.600000 dBA", "86.100000 dBA", "82.100000 dBA"]'::jsonb, 2, 'The field derating takes half of (30 - 7) off the level: 86.100000 dBA. 74.600000 dBA is Appendix B at the same label, the full (NRR - 7); 69.600000 dBA adds the dual 5 on top; 82.100000 dBA is the NIOSH earmuff row of the sweep, a different method.'),
  ('hygiene', 'intermediate', 'final', null, 14, 'In the NRR sweep, read the row for a 10.000000 dB label. Which level sits in the Appendix B column?', '["96.100000 dBA", "84.600000 dBA", "97.600000 dBA", "94.600000 dBA"]'::jsonb, 3, 'Appendix B takes (10 - 7) off the A-weighted level: 94.600000 dBA. 96.100000 dBA halves that credit, which is the field derating; 84.600000 dBA is Appendix B read on the 20.000000 dB row; 97.600000 dBA would mean no credit at all, which is what a label of 7 or less gets.'),
  ('hygiene', 'intermediate', 'final', null, 15, 'In the NRR sweep on the A-weighted teaching case, what does Appendix B leave at labels of 0.000000, 5.000000 and 7.000000 dB?', '["97.600000, 94.600000 and 92.600000 dBA, falling as the label rises", "0.000000, 92.600000 and 97.600000 dBA, rising as the label rises", "97.600000 dBA at all three, the unprotected level", "A refusal at 0.000000 dB and 97.600000 dBA at the other two labels"]'::jsonb, 2, 'Appendix B credits (NRR - 7) on A-weighted data, so a label of 7 or less leaves nothing to credit and the sweep prints 97.600000 dBA on all three rows. The falling figures 97.600000, 94.600000 and 92.600000 dBA are the dual-protection column of the same three rows. A label of zero or more is accepted, since the door refuses only an NRR that is negative or not a number.'),
  ('hygiene', 'intermediate', 'final', null, 16, 'Which two hearing protector methods does this course class as published and reproduced?', '["The NIOSH derating by type and the dual-protection rule, through the NIOSH criteria document and its tables", "Appendix B and the field derating, whose printed 80.000000 and 89.000000 dBA the engine matches", "Appendix B and the dual-protection rule, both of which subtract 7", "All four, since the engine reproduces each of them from its own source"]'::jsonb, 1, 'The manual''s example prints 89.000000 dBA under the field derating and 80.000000 dBA under Appendix B and the engine reproduces both, which is what PUBLISHED, REPRODUCED means. The NIOSH derating by type and the dual-protection 5 dB agree between the engine and an independent oracle with no printed value known to set against either, so section 23 records both as oracle only.'),
  ('hygiene', 'intermediate', 'final', null, 17, 'A report states: "NIOSH earmuff estimate 84.350000 dBA, reproduced from NIOSH''s printed tables." What is wrong with it?', '["The figure is wrong: the earmuff estimate on the teaching case is 77.600000 dBA.", "Nothing, because every protector method in the engine is reproduced against a printed table.", "The earmuff factor is licensed, so the figure may not appear in a report.", "The NIOSH derating by type is oracle only; no printed value is known to set against it, so nothing was reproduced."]'::jsonb, 3, 'The engine''s earmuff figure on the teaching case is 84.350000 dBA, but it is arithmetic on factors the engine and an independent oracle agree on, with no printed value behind it. The claim of reproduction is what is false. 77.600000 dBA is Appendix B, only two methods are reproduced, and the factors are not licensed.'),
  ('hygiene', 'intermediate', 'final', null, 18, 'The ten-hour IGBOMOTORU record reads 42.156250 ppm as an 8-hour TWA and 33.725000 ppm over the hours worked. Why is the TWA the higher?', '["The whole ten-hour sum is divided by 8, so the longer shift is charged as a larger chemical exposure.", "The engine adds a penalty of two hours for every shift longer than eight.", "The TWA uses the peak sample for the extra hours beyond the eighth.", "The engine applies a Brief and Scala factor to the ten-hour record."]'::jsonb, 0, '1910.1000(d)(1) divides the sum of concentration x time by 8 whatever the shift, so ten hours of chemical exposure over 8 hours reads above the average over the hours worked. There is no penalty term and no peak substitution, and adjusting a limit for an unusual shift is Expert tier material the 8-hour TWA does not apply.'),
  ('hygiene', 'intermediate', 'final', null, 19, 'Which expression is the 8-hour TWA that 29 CFR 1910.1000(d)(1) writes?', '["E = (C_a T_a + C_b T_b + ... + C_n T_n) / (T_a + T_b + ... + T_n)", "E = (C_a T_a + C_b T_b + ... + C_n T_n) / 8", "E = (C_a + C_b + ... + C_n) / n", "E = 10 log10( sum( T_i / 8 x 10^(C_i/10) ) )"]'::jsonb, 1, 'The regulation divides the concentration-hours by 8. Dividing by the hours covered is the average over the sampled time, which differs whenever a record is not 8 hours; the plain mean ignores time; and the logarithmic form is the LEX,8h energy average, which has no place in a chemical average.'),
  ('hygiene', 'intermediate', 'final', null, 20, 'A hygienist knows the worker on the IGBOMOTORU partial record left the area for the unsampled time. Which figure may they accept?', '["35.703704 ppm, the average over the 6.750000 hours the samples actually covered", "32.468750 ppm, the full-shift figure, since the fourth sample settles the question", "42.156250 ppm, the ten-hour figure, since the worker''s longer shift must be charged", "30.125000 ppm, the 8-hour TWA with the unsampled time counted as zero"]'::jsonb, 3, 'If the unsampled time was known to be clean, the regulation''s divide-by-8 figure, 30.125000 ppm, states the truth, and the report should still give the 6.750000 hours covered. 35.703704 ppm assumes the missing time looked like the sampled time; 32.468750 and 42.156250 ppm belong to other records.'),
  ('hygiene', 'intermediate', 'final', null, 21, 'The eleven-minute STEL record returns 92.333333 ppm with a warning. What does that warning oblige the report to state?', '["The minutes covered, since the rest of the window was counted as zero chemical exposure.", "The peak concentration, since the warning flags a sample above the short-term limit.", "An unusual shift adjustment of the limit, which the warning recommends for short records.", "Nothing, since a warning is informational and changes no figure the engine reports."]'::jsonb, 0, 'The engine''s warning is "the periods cover 11 min of 15: the remainder counts as zero exposure", so the figure rests on an assumption about four unsampled minutes and the report must say how much of the window was measured. The warning says nothing about a peak, the shift adjustment belongs to the ten-hour TWA warning, and a warning is part of the result.'),
  ('hygiene', 'intermediate', 'final', null, 22, 'The full STEL window returns 153.333333 ppm and the IGBOMOTORU full shift returns 32.468750 ppm. What makes the two different quantities?', '["One is an energy average and the other an arithmetic one, so the two can never be compared.", "One divides by the minutes it covers and the other by the hours it covers.", "One is a time weighted average over fifteen minutes and the other over eight hours, each set against its own limit.", "One is a peak reading and the other an average, so only the peak can pass a limit."]'::jsonb, 2, 'The STEL is sum(C t) / 15 with t in minutes and the 8-hour TWA is the concentration-hours over 8, so the two average different windows and each is set against its own limit. Both are arithmetic averages of concentrations and neither uses an energy relation; both divide by a fixed reference rather than by the time covered; and the STEL averages its window, since the full record holds a 240.000000 ppm sample inside a STEL of 153.333333 ppm.'),
  ('hygiene', 'intermediate', 'final', null, 23, 'Which of this tier''s doors takes its durations in minutes?', '["Every door in the tier, because the engine turns the hours it is given into minutes.", "`chemicalStel15Min` alone; the daily level and the 8-hour TWA both take hours.", "`chemicalStel15Min` and `lexWeeklyDbA`, because both of them read a short record.", "None of them, because a duration on any of this tier''s records is typed in hours."]'::jsonb, 1, 'The units rule is durations in hours for noise dose, LEX and the 8-hour chemical TWA, and in minutes for the STEL, and the doors take exactly that: `lexEightHourDbA` and `chemicalTwa8h` take periods of hours and `chemicalStel15Min` takes periods of minutes. The engine converts nothing it is given, and `lexWeeklyDbA` takes daily LEX,8h values with no durations in them at all.'),
  ('hygiene', 'intermediate', 'final', null, 24, 'In the published (d)(2) example, what term does 45.000000 against a limit of 200.000000 give?', '["0.200000", "0.225000", "0.500000", "0.925000"]'::jsonb, 1, '45.000000 over 200.000000 is 0.225000. 0.200000 is the term for 40.000000 against the same limit, 0.500000 the term for 500.000000 against 1000.000000, and 0.925000 the index of all three.'),
  ('hygiene', 'intermediate', 'final', null, 25, 'Ranked by their terms, how do the components of the teaching mixture stand?', '["Acetone 0.385000, xylene 0.312000, toluene 0.362500", "Toluene 0.362500, acetone 0.385000, xylene 0.312000", "Acetone 0.385000, toluene 0.362500, xylene 0.312000", "Xylene 0.312000, toluene 0.362500, acetone 0.385000"]'::jsonb, 2, 'Acetone at 385.000000 ppm over 1000.000000 is 0.385000, toluene at 72.500000 over 200.000000 is 0.362500, and xylene at 31.200000 over 100.000000 is 0.312000, so acetone leads and xylene is last. The other orderings misplace terms that sit close together, which is why no single component explains the excess.'),
  ('hygiene', 'intermediate', 'final', null, 26, 'The golden''s over-unity mixture gives an index of 1.100000. Beside the 1.000000 case, what does the pair show about J7?', '["Exceeds is true only when the index is strictly above 1, so 1.100000 exceeds and 1.000000 does not.", "Both exceed, since the regulation treats reaching unity as exceeding it.", "Neither exceeds, since the engine rounds an index to one decimal before comparing.", "Only 1.000000 exceeds, since the engine reads unity as the limit itself."]'::jsonb, 0, 'The regulation says the index "shall not exceed unity", and J7 reads that as written: an index of exactly 1 passes and 1.100000 is over. The engine does not round an index before comparing, and it does not treat equality as exceeding.'),
  ('hygiene', 'intermediate', 'final', null, 27, 'For the teaching mixture, which reading follows from each component acting on a different organ?', '["The index of 1.059500 still applies, since the regulation writes the sum.", "The index should be multiplied by three, one allowance per organ.", "The mixture cannot be assessed, since the engine refuses independent components.", "Each term is compared with 1 on its own, so no component is over its limit."]'::jsonb, 3, 'Where components act independently the sum means nothing, and each term, the largest being 0.385000, is read against 1 alone. The additive index assumes the same organ and mechanism; nothing multiplies it, and the engine computes the additive index whatever the mechanism because it cannot tell which case a mixture is in.'),
  ('hygiene', 'intermediate', 'final', null, 28, 'A mixture is sent to `mixtureExposureIndex` with no components at all. What comes back?', '["An index of 0.000000 with exceeds false, since nothing was present to add", "A refusal on `components[0].limit`, naming the limit that is missing from the list", "A refusal on `components`: \"components must be a non-empty array\"", "An index of 1.000000, the default the engine returns for an empty mixture list"]'::jsonb, 2, 'An empty mixture has no index, so the engine refuses on the field `components` in its own words. It returns no default index, and the per-component limit refusal applies only when a component is present with a limit of zero.'),
  ('hygiene', 'intermediate', 'final', null, 29, 'The Associate tier''s OBEN walkdown has six periods, and the OSHA PEL noise dose integrates 2 of them. How many would a LEX,8h over the same periods include?', '["All 6, since LEX,8h has no threshold", "2, the same periods the PEL integrates", "5, the periods at or above 80 dBA", "None, since LEX,8h cannot read a dosimeter record"]'::jsonb, 0, 'LEX,8h is an energy average with no floor, so every period counts, including the 76.500000 dBA period no noise dose criterion integrates. 2 is the PEL''s count with its 90 dBA threshold and 5 is the count at the 80 dBA threshold of the action level and the NIOSH noise REL.'),
  ('hygiene', 'intermediate', 'final', null, 30, 'A TWA of 85 on the OSHA action-level scale is a noise dose of 50.000750 percent. How does that relate to the EU upper action value of 85?', '["They are the same limit written two ways, so either figure can be quoted for the other.", "They are different metrics that share a number: a TWA on a decibel exchange rate of 5 dB with a threshold, and a LEX,8h on the energy relation with none.", "The EU value is the OSHA action level converted into noise exposure points.", "The OSHA value is the EU value after the 7 dB weighting allowance."]'::jsonb, 1, 'The OSHA action level is 85 dBA as a TWA, equivalently a noise dose of fifty percent, built with a decibel exchange rate of 5 dB and an 80 dBA threshold. The EU upper action value is a LEX,8h of 85 dBA, which is 100 points. The 7 dB belongs to protector estimates and has nothing to do with either.'),
  ('hygiene', 'intermediate', 'final', null, 31, 'The engine measures one of its constants by asking for the LEX,8h of 100 noise exposure points. Which constant is it?', '["The reference duration T0, 8.000000000000 hours", "The chemical TWA divisor, 8.000000000000 hours", "The EU limit value, 87.000000000000 dBA", "The exposure points pivot, 85.000000000000 dBA"]'::jsonb, 3, '100 points is LEX,8h 85 by definition, so asking for their level returns the pivot. T0 is measured from the LEX of 4 hours at 90 dBA, the chemical divisor from 10 ppm for one hour, and the EU values are exported rather than measured.'),
  ('hygiene', 'intermediate', 'final', null, 32, 'How does the engine measure the Appendix B subtraction of 7.000000000000 dB?', '["As 30 less the attenuation Appendix B gives at an NRR of 30", "As the attenuation divided by (NRR less 7) at an NRR of 27, on A-weighted data", "As the credited NRR over 40 on C-weighted data, for an earmuff label", "As the attenuation less (NRR less 7) at an NRR of 30, on A-weighted data"]'::jsonb, 0, 'At NRR 30 Appendix B credits 30 - 7 on A-weighted data, so 30 less that attenuation returns the 7. The attenuation over (NRR - 7) at NRR 27 measures the field derating''s 0.500000000000, the credited NRR over 40 measures the NIOSH deratings, and the attenuation less (NRR - 7) measures the dual-protection 5.'),
  ('hygiene', 'intermediate', 'final', null, 33, 'A weekly LEX call is handed eight daily values. What does the engine answer, in its own words?', '["\"dailyLexDbA must be a non-empty array of daily exposures\"", "\"dailyLexDbA[1] must be a finite number\"", "\"dailyLexDbA holds more than 7 days: a week has 7\"", "A weekly level with the energy sum divided by 8 in place of 5"]'::jsonb, 2, 'The weekly LEX accepts at most seven days, as J10 records, and refuses an eighth on the field `dailyLexDbA`. The non-empty message is the refusal for a week with no days and the indexed message the refusal for a day that is not a number; the engine never changes its divisor to fit the count.'),
  ('hygiene', 'intermediate', 'final', null, 34, 'A LEX,8h call is given 100.000000 dBA for 0.000000 h beside 85.000000 dBA for 8.000000 h. What does the engine report?', '["100.000000 dBA, since the loudest task on the list sets the level of the whole day", "85.000000 dBA, with the zero-length task''s own task LEX reported as absent", "A refusal on `periods`, since a task of zero hours cannot be entered on a LEX list", "85.969100 dBA, since the loud task still adds a small share of energy to the day"]'::jsonb, 1, 'A task of zero hours carries no energy, so the day is 85.000000 dBA and 100.000000 points exactly as if the loud entry were not there, and its own task LEX has no value to report. Zero hours is accepted, the loudest level does not set a day, and 85.969100 dBA is ten hours at 85 dBA.'),
  ('hygiene', 'intermediate', 'final', null, 35, 'The engine takes concentrations in whatever unit the caller types. What must hold before a mixture term means anything?', '["The concentration is in ppm and the limit in mg/m3, the way OSHA prints them in its own tables.", "Nothing, because the engine converts every unit by itself from the substance name it is given.", "The limit is in ppm-hours, so that it matches the 8-hour TWA it is later compared with in a report.", "The concentration and its limit are in the same unit, since each term is a ratio of the two."]'::jsonb, 3, 'A term built from a concentration in one unit and a limit in another is a wrong number that looks like a right one, and the arithmetic gives no warning; this course keeps both in ppm. The engine takes no substance name and converts nothing, and a limit is a concentration, never a concentration-time product.'),
  ('hygiene', 'intermediate', 'final', null, 36, 'A safety case quotes a 5x5 risk matrix beside the tier''s noise exposure figures. Which course owns that matrix?', '["The Risk, Change and Learning course", "This course, in its capstone module", "The Safety Performance Statistics course", "The Separation and Relief courses"]'::jsonb, 0, 'A risk matrix ranks hazards by likelihood and consequence, and it is taught in Risk, Change and Learning; this course only cites it beside its figures. The statistics course owns rates of recordable events, and the relief courses own radiant flux from flares, so neither is the home of the matrix.'),
  ('hygiene', 'intermediate', 'final', null, 37, 'Where do heat stress limits and margins stand in this course, as the Professional tier describes them?', '["In this tier, graded through the field derated estimate", "In the Expert tier, graded as margins against the NIOSH heat REL", "Nowhere, since heat stress belongs to the Separation and Relief courses", "In the Expert tier, never graded, because the equation constants are checked for transcription only"]'::jsonb, 3, 'Every heat stress limit and margin is taught in the Expert tier and never graded, because the constants are transcription only. The field derating is a hearing protector method, no margin is graded, and flare radiation, which the Separation and Relief courses own, is a radiant flux and a different subject from heat stress.'),
  ('hygiene', 'intermediate', 'final', null, 38, 'Why does this course always write "NIOSH noise REL" or "NIOSH heat REL" and never the acronym alone?', '["The acronym alone is the licensed trade name of a NIOSH document and cannot be quoted in a course.", "Because the NIOSH noise REL is withdrawn, and only the heat stress limit is still in force today.", "Two different NIOSH limits, one for noise and one for heat stress, share the acronym, and the qualifier says which is meant.", "The qualifier tells the reader which decibel exchange rate was used to compute the figure."]'::jsonb, 2, 'Section 24 binds the two qualified forms because the NIOSH recommended exposure limit for noise, met in the Associate tier, and the one for heat stress, met in the Expert tier, share the letters. The acronym names no licensed document, the NIOSH noise REL is a live criterion the engine presets, and a decibel exchange rate is stated on its own beside a figure.'),
  ('hygiene', 'intermediate', 'final', null, 39, 'A LEX,8h of exactly 85.000000 dBA is read against the EU values. What do the engine''s two action flags say?', '["Lower true and upper false, because a figure sitting on a value has not passed it", "Both true, because each flag reads at or above its value", "Both false, because the engine raises a flag only above the value itself", "Lower true and upper absent, because the upper flag needs the limit value too"]'::jsonb, 1, 'The small cases print eight hours at 85 dBA as 85.000000 dBA and 100.000000 points with the lower action flag true and the upper action flag true, and the digest states that the two flags are at or above. A figure sitting on a value has reached it. The limit value of 87.000000 dBA carries no flag at all, because it applies at the ear with protection taken into account, which the engine does not compute.'),
  ('hygiene', 'intermediate', 'final', null, 40, 'Which statement about the engine''s limits for chemicals is right?', '["Every limit is an input the caller types; the engine holds no limit table and compares with no ceiling.", "The engine looks up the OSHA limit for each named substance.", "The engine holds a licensed table of TLVs as a fallback.", "The engine compares every TWA with a ceiling value automatically."]'::jsonb, 0, 'Every exposure limit is an input, and the engine has no door for a chemical ceiling comparison. It holds no table of any kind, public or licensed; ACGIH TLVs are never quoted in this course.'),
  ('hygiene', 'intermediate', 'final', null, 41, 'Which of these is a judgement call the engine makes where its sources leave the choice open?', '["The NIOSH derating factors being printed values it reproduces from the source''s own table", "A mixture index being a product of its terms, so one small term pulls the index down", "LEX,8h carrying an 80 dBA threshold, like the OSHA action level and the NIOSH noise REL", "J6: the 8-hour chemical TWA always divides by 8 and warns under or over 8 hours"]'::jsonb, 3, 'J6 is the engine''s stated choice for the chemical averages, named with J5, J7 and J10 in this tier. The NIOSH factors are ORACLE ONLY with no printed value behind them, the index is a sum, and LEX,8h has no threshold at all.'),
  ('hygiene', 'intermediate', 'final', null, 42, 'This course writes "sound level" for an instrument reading. Which courses make that rule necessary?', '["The Economics courses, where the short word already means a currency rate", "Flow Assurance and Gas Processing, where the short word means an inhibitor or a methanol charge", "Decline Curve Analysis, Well Test and Seismolord, where the short word means scatter in data", "Field Development Planning and Well Cost, where the short word means money that is at risk"]'::jsonb, 2, 'Section 24 rule 3 names those three courses, where the short word already means scatter in data, so this course says sound level for a reading. The Economics collision is the one that forces "decibel exchange rate", the Flow Assurance and Gas Processing collision forces "noise dose", and the Field Development Planning and Well Cost collision forces a qualified "noise exposure" or "chemical exposure".');
